Rules.InvariantScript:
// Initializes the visibility variables used by the overlay and side panes.

    // Sets the overlay visibility to hidden.

        Set(varViewOverlay, false);

    // Sets the columns, filter, and details (quickview) panes to hidden.

        Set(varViewPaneColumns, false);
        Set(varViewPaneFilter, false);
        Set(varViewPaneDetails, false);

        Set(varViewPaneFilterTab, "Filter");


// Set the default resource type (microsoft.powerautomate/cloudflows for example)

    Set(varResourceType, "microsoft.powerautomate/cloudflows");


// Stores the default search clause as JSON text. The clause filters inventory resources to Power Automate cloud flows.

    Set( 
        varClause, 
        "
            [
                {
                    ""$type"": ""where"", 
                    ""FieldName"": ""type"",
                    ""Operator"": ""=="",
                    ""Values"": [
                        ""'" & varResourceType & "'""
                    ]
                }
            ]
        "
    );


// Runs the inventory search flow with the default search clause. Parses the JSON returned in the data property into the inventory table type. Stores the parsed result in varInventory. 

    Set(
        varInventory,
        ParseInventory(
            'PPAT-SearchInventory'.Run(varClause).data
        )
    );


// Replaces the contents of colInventoryColumns with the column configuration defined by nfInventoryColumns

    ClearCollect(
        colInventoryColumns,
        nfInventoryColumns
    );


// Create list of operators 

    ClearCollect(
        colInventoryOperators,
        { DisplayOrder: 1, Operator: "Equals", Displayname: "Equals", QueryOperator: "==", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 2, Operator: "DoesNotEqual", Displayname: "Does not equal", QueryOperator: "!=", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 3, Operator: "Contains", Displayname: "Contains", QueryOperator: "contains", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 4, Operator: "DoesNotContain", Displayname: "Does not contain", QueryOperator: "!contains", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 5, Operator: "StartsWith", Displayname: "Begins with", QueryOperator: "startswith", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 6, Operator: "DoesNotBeginWith", Displayname: "Does not begin with", QueryOperator: "!startswith", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 7, Operator: "EndsWith", Displayname: "Ends with", QueryOperator: "endswith", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 8, Operator: "DoesNotEndWith", Displayname: "Does not end with", QueryOperator: "!endswith", FieldTypes: ["String", "LookUp"] },
        { DisplayOrder: 9, Operator: "On", Displayname: "On", QueryOperator: "", FieldTypes: ["DateTime"] },
        { DisplayOrder: 10, Operator: "OnOrAfter", Displayname: "On or after", QueryOperator: "", FieldTypes: ["DateTime"] },
        { DisplayOrder: 11, Operator: "OnOrBefore", Displayname: "On or before", QueryOperator: "", FieldTypes: ["DateTime"] },
        { DisplayOrder: 12, Operator: "Yesterday", Displayname: "Yesterday", QueryOperator: "", FieldTypes: ["DateTime"] },
        { DisplayOrder: 13, Operator: "Today", Displayname: "Today", QueryOperator: "", FieldTypes: ["DateTime"] },
        { DisplayOrder: 14, Operator: "Tomorrow", Displayname: "Tomorrow", QueryOperator: "", FieldTypes: ["DateTime"] }
    );


// Create a filter collection 

    ClearCollect( 
        colInventoryFilter,
        {
            id: GUID(), 
            field: First(colInventoryColumns),
            operator: First(colInventoryOperators), 
            value: "",
            enabled: true
        }
    );

    Clear(colInventoryFilter);
